const skjema = document.querySelector("#kalkulator");
skjema.addEventListener("submit", (event) => {
  event.preventDefault();
  const felt = document.querySelector("#antall");
  const antall = Number(felt.value);
  const svar = document.querySelector("#svar");
  if (felt.value.trim() === "" || !Number.isInteger(antall) || antall < 1) {
    svar.textContent = "Skriv et positivt heltall.";
    return;
  }
  svar.textContent = "Pris: " + antall * 25 + " kr";
});

